// Primary template declaration (function)
template <typename T>
T get_default_value() { return T{}; }

// Explicit specialization for 'int'
template <>
int get_default_value<int>() { return 42; }

// Primary template declaration (class)
template <typename T>
struct Processor {
    void process() {}
};

// Explicit specialization for 'bool'
template <>
struct Processor<bool> {
    void process() { /* Custom bool logic */ }
};

// Explicit specialization declaration
extern template class Processor<double>;

// Explicit specialization definition (defined elsewhere)
template class Processor<double>;
